mod solution;

fn main() {
    let cases = [
    (r#"candidates=[2,3,6,7]"#, r#"2,2,3;7"#),
    (r#"candidates=[7]"#, r#"7"#),
    (r#"
candidates=[7]
"#, r#"7"#),
    (r#"  
candidates=[2,3,6,7]
  "#, r#"2,2,3;7"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS combination-sum");
}
